/* ============================================================
   GAME
   ============================================================ */

const CATS = Object.keys(QBANK);
const LAST = 60;

const emptyFx = () => ({ onlyHigh: false, backslide: 0, cap2: 0, skip: false });

const titleCase = (s) => s.toLowerCase().replace(/(^|[\s&])([a-z])/g, (m, a, b) => a + b.toUpperCase());

function tileInfo(pos) {
  if (pos >= LAST) return { kind: "x", title: "The Reckoning", icon: "crown" };
  if (pos === 0) return { kind: "s", title: "The start", icon: "play" };
  const t = BOARD[pos];
  if (t.k === "c") return { kind: "c", title: titleCase(t.c), code: CAT_SHORT[t.c], icon: CAT_ICON[t.c] };
  if (t.k === "f") return { kind: "f", title: "Fortune", icon: "star" };
  return { kind: "m", title: "Misfortune", icon: "alert" };
}

/* ---------------- saved game + phone-app helpers ---------------- */
const SAVE_KEY = "triviate-save-v1";
function readSave() {
  try {
    const s = JSON.parse(window.localStorage.getItem(SAVE_KEY) || "null");
    return s && s.v === 1 && Array.isArray(s.teams) && s.teams.length ? s : null;
  } catch (e) {
    return null;
  }
}
function writeSave(s) {
  try {
    window.localStorage.setItem(SAVE_KEY, JSON.stringify(s));
  } catch (e) {}
}
function clearSave() {
  try {
    window.localStorage.removeItem(SAVE_KEY);
  } catch (e) {}
}

/* install button (Android/desktop Chrome) and the iPhone hint; only inside the installed-app build */
function useInstall() {
  const hasWin = typeof window !== "undefined";
  const [promptEvt, setPromptEvt] = useState(() => (hasWin && window.__triviateInstall) || null);
  useEffect(() => {
    const on = () => setPromptEvt(window.__triviateInstall || null);
    const done = () => {
      window.__triviateInstall = null;
      setPromptEvt(null);
    };
    window.addEventListener("triviate-installable", on);
    window.addEventListener("appinstalled", done);
    return () => {
      window.removeEventListener("triviate-installable", on);
      window.removeEventListener("appinstalled", done);
    };
  }, []);
  const isApp = hasWin && window.__triviateApp === true;
  const standalone =
    hasWin &&
    ((window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) ||
      window.navigator.standalone === true);
  const ua = hasWin ? window.navigator.userAgent : "";
  const ios = /iphone|ipad|ipod/i.test(ua) || (/Macintosh/.test(ua) && hasWin && window.navigator.maxTouchPoints > 1);
  async function install() {
    const p = window.__triviateInstall;
    if (!p) return;
    p.prompt();
    try {
      await p.userChoice;
    } catch (e) {}
    window.__triviateInstall = null;
    setPromptEvt(null);
  }
  return { canInstall: isApp && !!promptEvt && !standalone, iosHint: isApp && ios && !standalone, install };
}

export default function RateYourself() {
  const [phase, setPhase] = useState("setup");
  const [teamCount, setTeamCount] = useState(2);
  const [names, setNames] = useState(TEAM_COLORS.map((t) => t.name));

  const [teams, setTeams] = useState([]);
  const [turn, setTurn] = useState(0);
  const [topic, setTopic] = useState(null);
  const [wager, setWager] = useState(null);
  const [outcome, setOutcome] = useState(null);
  const [pending, setPending] = useState(null);
  const [misf, setMisf] = useState(null);
  const [fortuneQ, setFortuneQ] = useState(null);
  const [ticks, setTicks] = useState(() => new Set());
  const [orderQ, setOrderQ] = useState(null);
  const [pick, setPick] = useState([]);
  const [showBoard, setShowBoard] = useState(false);
  const [saved, setSaved] = useState(() => (typeof window !== "undefined" ? readSave() : null));
  const [confirmDelete, setConfirmDelete] = useState(false);
  const inst = useInstall();

  const usedT = useRef(new Set());
  const usedF = useRef(new Set());
  const usedO = useRef(new Set());
  const panelRef = useRef(null);

  const reduced =
    typeof window !== "undefined" &&
    window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const POOL = useMemo(() => {
    const m = {};
    for (const cat of CATS) m[cat] = QBANK[cat].map((t) => ({ cat, sub: t.sub, q: t.q }));
    return m;
  }, []);

  function pickFrom(arr, usedRef) {
    const used = usedRef.current;
    if (used.size >= arr.length) used.clear();
    let i = 0;
    for (let g = 0; g < 9000; g++) {
      i = Math.floor(Math.random() * arr.length);
      if (!used.has(i)) break;
    }
    used.add(i);
    return arr[i];
  }
  const drawTopic = (cat) => pickFrom(POOL[cat], usedT);
  const drawFortune = () => pickFrom(FORTUNE, usedF);
  function drawOrder() {
    const o = pickFrom(ORDERS, usedO);
    const shuffled = [...o.list];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return { ...o, shuffled };
  }

  function startGame() {
    setTeams(
      TEAM_COLORS.slice(0, teamCount).map((tc, i) => ({
        name: (names[i] || "").trim() || tc.name,
        color: tc.color,
        pos: 0,
        swaps: 1,
        fx: emptyFx(),
      }))
    );
    usedT.current = new Set();
    usedF.current = new Set();
    usedO.current = new Set();
    setTurn(0);
    setTopic(null);
    setWager(null);
    setOutcome(null);
    setMisf(null);
    setShowBoard(false);
    setPhase("turn");
  }

  /* pawn steps one space at a time, forwards or back */
  useEffect(() => {
    if (!pending) return;
    if (pending.remaining <= 0) {
      const landed = teams[pending.idx].pos;
      setPending(null);
      if (pending.kind === "toll") setPhase("misfortune");
      else land(pending.idx, landed);
      return;
    }
    const t = setTimeout(
      () => {
        setTeams((ts) =>
          ts.map((tm, i) =>
            i === pending.idx
              ? { ...tm, pos: Math.max(0, Math.min(tm.pos + pending.dir, LAST)) }
              : tm
          )
        );
        setPending((p) => (p ? { ...p, remaining: p.remaining - 1 } : null));
      },
      reduced ? 0 : 160
    );
    return () => clearTimeout(t);
  }, [pending, reduced]); // eslint-disable-line

  function land(idx, newPos) {
    if (newPos >= LAST) {
      setOrderQ(drawOrder());
      setPick([]);
      setPhase("final");
      return;
    }
    const tile = BOARD[newPos];
    if (tile && tile.k === "m") {
      fireMisfortune(idx);
      return;
    }
    setPhase("result");
  }

  function fireMisfortune(idx) {
    const m = MISFORTUNES[Math.floor(Math.random() * MISFORTUNES.length)];
    setMisf(m);
    if (m.id === "toll") {
      const back = Math.min(4, teams[idx].pos);
      setPending({ idx, remaining: back, dir: -1, kind: "toll" });
      return;
    }
    setTeams((ts) =>
      ts.map((t, i) => {
        if (i !== idx) return t;
        const fx = { ...t.fx };
        let swaps = t.swaps;
        if (m.id === "heavy") fx.onlyHigh = true;
        if (m.id === "backslide") fx.backslide = 4;
        if (m.id === "cold") fx.cap2 = 2;
        if (m.id === "nerve") swaps = 0;
        if (m.id === "beat") fx.skip = true;
        return { ...t, fx, swaps };
      })
    );
    setPhase("misfortune");
  }

  function beginTurn() {
    const t = teams[turn];
    if (t.fx.skip) {
      setTeams((ts) => ts.map((x, i) => (i === turn ? { ...x, fx: { ...x.fx, skip: false } } : x)));
      setOutcome({ kind: "skipped" });
      setPhase("result");
      return;
    }
    if (t.pos >= LAST) {
      setOrderQ(drawOrder());
      setPick([]);
      setPhase("final");
      return;
    }
    const tile = t.pos === 0 ? null : BOARD[t.pos];
    if (tile && tile.k === "f") {
      setFortuneQ(drawFortune());
      setTicks(new Set());
      setPhase("fortune");
      return;
    }
    const cat = tile && tile.k === "c" ? tile.c : CATS[Math.floor(Math.random() * CATS.length)];
    setTopic(drawTopic(cat));
    setWager(null);
    setPhase("wager");
  }

  function allowed(fx) {
    if (fx.cap2 > 0) return [1, 2];
    if (fx.onlyHigh) return [4, 5];
    return [1, 2, 3, 4, 5];
  }

  function swapTopic() {
    const t = teams[turn];
    if (t.swaps <= 0) return;
    setTeams((ts) => ts.map((x, i) => (i === turn ? { ...x, swaps: x.swaps - 1 } : x)));
    setTopic(drawTopic(topic.cat));
  }

  function judge(correct) {
    const t = teams[turn];
    setOutcome({ kind: correct ? "right" : "wrong", wager });
    if (correct) {
      setPhase("move");
      setPending({ idx: turn, remaining: Math.min(wager, LAST - t.pos), dir: 1 });
    } else if (t.fx.backslide > 0) {
      setPhase("move");
      setPending({ idx: turn, remaining: Math.min(wager, t.pos), dir: -1 });
    } else {
      setPhase("result");
    }
  }

  function scoreFortune() {
    const n = ticks.size;
    setOutcome({ kind: "fortune", n });
    if (n === 0) {
      setPhase("result");
      return;
    }
    setPhase("move");
    setPending({ idx: turn, remaining: Math.min(n, LAST - teams[turn].pos), dir: 1 });
  }

  function lockOrder() {
    const right = orderQ.list.every((v, i) => pick[i] === v);
    setOutcome({ kind: right ? "won" : "failed" });
    setPhase(right ? "win" : "finalResult");
  }

  function nextTurn() {
    setTeams((ts) =>
      ts.map((t, i) =>
        i === turn
          ? {
              ...t,
              fx: {
                ...t.fx,
                backslide: Math.max(0, t.fx.backslide - 1),
                cap2: Math.max(0, t.fx.cap2 - 1),
              },
            }
          : t
      )
    );
    setTurn((t) => (t + 1) % teams.length);
    setTopic(null);
    setWager(null);
    setOutcome(null);
    setMisf(null);
    setFortuneQ(null);
    setOrderQ(null);
    setPhase("turn");
  }

  /* save after every settled step, so a closed app can resume */
  useEffect(() => {
    if (phase === "setup" || pending) return;
    if (phase === "win") {
      clearSave();
      return;
    }
    writeSave({
      v: 1,
      phase,
      teams,
      turn,
      topic,
      wager,
      outcome,
      misf,
      fortuneQ,
      ticks: [...ticks],
      orderQ,
      pick,
      usedT: [...usedT.current],
      usedF: [...usedF.current],
      usedO: [...usedO.current],
      at: Date.now(),
    });
  }, [phase, teams, turn, topic, wager, outcome, misf, fortuneQ, ticks, orderQ, pick, pending]);

  /* keep the screen awake during a game */
  const inGame = phase !== "setup";
  useEffect(() => {
    if (!inGame || typeof navigator === "undefined" || !navigator.wakeLock) return;
    let lock = null;
    let alive = true;
    const get = async () => {
      try {
        lock = await navigator.wakeLock.request("screen");
      } catch (e) {}
    };
    get();
    const onVis = () => {
      if (alive && document.visibilityState === "visible") get();
    };
    document.addEventListener("visibilitychange", onVis);
    return () => {
      alive = false;
      document.removeEventListener("visibilitychange", onVis);
      if (lock) lock.release().catch(() => {});
    };
  }, [inGame]);

  function resumeGame() {
    const g = saved;
    if (!g) return;
    usedT.current = new Set(g.usedT || []);
    usedF.current = new Set(g.usedF || []);
    usedO.current = new Set(g.usedO || []);
    setTeams(g.teams);
    setTurn(g.turn || 0);
    setTopic(g.topic || null);
    setWager(g.wager == null ? null : g.wager);
    setOutcome(g.outcome || null);
    setMisf(g.misf || null);
    setFortuneQ(g.fortuneQ || null);
    setTicks(new Set(g.ticks || []));
    setOrderQ(g.orderQ || null);
    setPick(g.pick || []);
    setShowBoard(false);
    setPhase(g.phase === "move" ? "result" : g.phase);
  }

  useEffect(() => {
    if (!panelRef.current || phase === "setup" || reduced) return;
    panelRef.current.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }, [phase]); // eslint-disable-line

  const me = teams[turn];
  const nextName = teams.length ? teams[(turn + 1) % teams.length].name : "";

  /* ---------------- SETUP ---------------- */
  if (phase === "setup") {
    return (
      <Shell>
        <div className="ry-wrap">
          <header className="ry-hero">
            <p className="ry-label">A board game for one phone</p>
            <h1 className="ry-d ry-title">Triviate</h1>
            <p className="ry-lede">
              No dice. Before each question you say how good you are, from <b>1 to 5</b>. That
              number is both the difficulty and the number of spaces you move.
            </p>
          </header>

          {saved && (
            <section className="ry-card ry-resume" aria-label="Game in progress">
              <p className="ry-label">Game in progress</p>
              <div className="ry-standings">
                {saved.teams.map((t, i) => (
                  <span key={i} className={"ry-stand" + (i === saved.turn ? " is-me" : "")}>
                    <span className="ry-dot" style={{ background: t.color }} aria-hidden="true" />
                    {t.name}
                    <b>{t.pos}</b>
                  </span>
                ))}
              </div>
              <p className="ry-sub">
                Next up: <b>{(saved.teams[saved.turn] || saved.teams[0]).name}</b>. Starting a new game replaces this one.
              </p>
              <button className="ry-btn ry-primary" onClick={resumeGame}>
                Resume game <Icon name="arrow" />
              </button>
              <button
                className="ry-btn ry-ghost"
                onClick={() => {
                  if (confirmDelete) {
                    clearSave();
                    setSaved(null);
                    setConfirmDelete(false);
                  } else setConfirmDelete(true);
                }}
              >
                {confirmDelete ? "Tap again to delete it" : "Delete this game"}
              </button>
            </section>
          )}

          <ul className="ry-rules">
            <li>
              <span className="ry-rule-ic ry-ic-accent"><Icon name="grid" /></span>
              <span><b>Sixty tiles</b>The tile you stand on picks your category.</span>
            </li>
            <li>
              <span className="ry-rule-ic ry-ic-fortune"><Icon name="star" fill /></span>
              <span><b>Fortune and misfortune</b>Name as many as you can, or take a setback.</span>
            </li>
            <li>
              <span className="ry-rule-ic ry-ic-reckon"><Icon name="crown" /></span>
              <span><b>The Reckoning</b>Tile 60: put five things in exact order to win.</span>
            </li>
          </ul>

          <section className="ry-card">
            <p className="ry-label">Teams</p>
            <div className="ry-count" role="group" aria-label="Number of teams">
              {[2, 3, 4, 5].map((n) => (
                <button
                  key={n}
                  className={"ry-lv" + (teamCount === n ? " is-on" : "")}
                  aria-pressed={teamCount === n}
                  onClick={() => setTeamCount(n)}
                >
                  <span className="ry-d ry-lv-n">{n}</span>
                </button>
              ))}
            </div>
            <div className="ry-names">
              {TEAM_COLORS.slice(0, teamCount).map((tc, i) => (
                <label key={i} className="ry-name-row">
                  <span className="ry-dot ry-dot-lg" style={{ background: tc.color }} aria-hidden="true" />
                  <span className="ry-sr">{"Team " + (i + 1) + " name"}</span>
                  <input
                    className="ry-input"
                    value={names[i]}
                    maxLength={14}
                    onChange={(e) => {
                      const v = [...names];
                      v[i] = e.target.value;
                      setNames(v);
                    }}
                  />
                </label>
              ))}
            </div>
          </section>

          <button className="ry-btn ry-primary" onClick={startGame}>
            Set out the board <Icon name="arrow" />
          </button>

          {inst.canInstall && (
            <button className="ry-btn ry-ghost" onClick={inst.install}>
              <Icon name="download" /> Install Triviate on this phone
            </button>
          )}
          {inst.iosHint && (
            <p className="ry-hint ry-ios">
              To install on iPhone: tap <b>Share</b>, then <b>Add to Home Screen</b>.
            </p>
          )}
        </div>
      </Shell>
    );
  }

  /* ---------------- WIN ---------------- */
  if (phase === "win") {
    return (
      <Shell>
        <div className="ry-wrap">
          <section className="ry-card ry-win">
            <span className="ry-win-ic" style={{ color: me.color }}><Icon name="trophy" size={56} stroke={1.8} /></span>
            <p className="ry-label">The Reckoning is answered</p>
            <h1 className="ry-d ry-title" style={{ color: me.color }}>{me.name} wins</h1>
            <ol className="ry-proof">
              {orderQ.list.map((v, i) => (
                <li key={i} className="ry-proof-row">
                  <span className="ry-slot-n is-good">{i + 1}</span>
                  <span className="ry-proof-v">{v}</span>
                  <span className="ry-good"><Icon name="check" size={18} /></span>
                </li>
              ))}
            </ol>
          </section>
          <Board teams={teams} activeIdx={turn} />
          <button
            className="ry-btn ry-primary"
            onClick={() => {
              clearSave();
              setSaved(null);
              setConfirmDelete(false);
              setPhase("setup");
            }}
          >
            Play again
          </button>
        </div>
      </Shell>
    );
  }

  const allow = allowed(me.fx);
  const fxNotes = [];
  if (me.fx.onlyHigh) fxNotes.push("Only level 4 or 5");
  if (me.fx.cap2 > 0) fxNotes.push("Capped at 2 for " + me.fx.cap2 + (me.fx.cap2 === 1 ? " turn" : " turns"));
  if (me.fx.backslide > 0) fxNotes.push("Backslide for " + me.fx.backslide + (me.fx.backslide === 1 ? " turn" : " turns"));
  if (me.swaps === 0) fxNotes.push("No topic swap");

  const here = tileInfo(me.pos);
  const q = topic && wager ? topic.q[wager - 1] : null;
  const destPos = wager ? Math.min(me.pos + wager, LAST) : null;
  const dest = destPos ? tileInfo(destPos) : null;

  /* ---------------- PLAY ---------------- */
  return (
    <Shell>
      <div className="ry-wrap">
        <header className="ry-head">
          <div className="ry-who">
            <span
              className="ry-d ry-avatar"
              style={{ background: me.color, boxShadow: "0 0 0 3px var(--bg), 0 0 0 5px " + me.color }}
              aria-hidden="true"
            >
              {me.name.slice(0, 1).toUpperCase()}
            </span>
            <div>
              <p className="ry-who-kick">Your turn</p>
              <p className="ry-d ry-who-name">{me.name}</p>
              <p className="ry-who-sub">
                {me.pos === 0
                  ? "At the start · " + LAST + " to the Reckoning"
                  : me.pos >= LAST
                  ? "On the Reckoning"
                  : "Tile " + me.pos + " of " + LAST + " · " + (LAST - me.pos) + " to go"}
              </p>
            </div>
          </div>
          <button
            className="ry-icon-btn"
            aria-label={showBoard ? "Hide the full board" : "Show the full board"}
            aria-expanded={showBoard}
            onClick={() => setShowBoard((v) => !v)}
          >
            <Icon name={showBoard ? "x" : "grid"} size={22} />
          </button>
        </header>

        {fxNotes.length > 0 && (
          <div className="ry-fx" role="status">
            {fxNotes.map((n) => (
              <span key={n} className="ry-fx-chip"><Icon name="alert" size={14} />{n}</span>
            ))}
          </div>
        )}

        {showBoard ? <Board teams={teams} activeIdx={turn} /> : <Strip teams={teams} activeIdx={turn} />}

        <div ref={panelRef} className="ry-stack">
          {/* ---- handoff ---- */}
          {phase === "turn" && (
            <>
              <section className={"ry-card ry-turn ry-k-" + here.kind}>
                <p className="ry-label">You are standing on</p>
                <div className="ry-turn-row">
                  <span className="ry-turn-ic"><Icon name={here.icon} size={26} fill={here.kind === "f"} /></span>
                  <h2 className="ry-d ry-turn-title">{here.title}</h2>
                </div>
                <p className="ry-sub">
                  {me.pos >= LAST
                    ? "Five things. One exact order. Get it perfect and you win."
                    : me.pos === 0
                    ? "Your first question comes from any category."
                    : here.kind === "f"
                    ? "Name as many as you can. One space per answer."
                    : here.kind === "m"
                    ? "The damage is done. Your question comes from any category."
                    : "Your question comes from this category."}
                </p>
              </section>
              <button className="ry-btn ry-primary" onClick={beginTurn}>
                {me.pos >= LAST ? "Face the reckoning" : "Begin"}
                <Icon name="arrow" />
              </button>
            </>
          )}

          {/* ---- choose a level ---- */}
          {phase === "wager" && topic && (
            <>
              <section className="ry-cat">
                <span className="ry-cat-deco" aria-hidden="true"><Icon name={CAT_ICON[topic.cat]} size={132} stroke={1.4} /></span>
                <p className="ry-label ry-on-accent">{here.kind === "c" ? "You landed on" : "Your category"}</p>
                <h2 className="ry-d ry-cat-title">{titleCase(topic.cat)}</h2>
                <div className="ry-topic-row">
                  <span className="ry-chip">{topic.sub}</span>
                  {me.swaps > 0 && (
                    <button className="ry-swap" onClick={swapTopic}>
                      <Icon name="swap" size={16} />
                      Swap · {me.swaps} left
                    </button>
                  )}
                </div>
              </section>

              <section aria-labelledby="ry-ask">
                <h3 id="ry-ask" className="ry-d ry-h">How sure are you?</h3>
                <p className="ry-sub">Your level is your dice roll. Aim high, move far.</p>
                <div className="ry-levels" role="group" aria-label="Choose a level">
                  {LEVELS.map((l) => {
                    const ok = allow.includes(l.n);
                    const on = wager === l.n;
                    return (
                      <button
                        key={l.n}
                        data-level={l.n}
                        className={"ry-lv" + (on ? " is-on" : "")}
                        disabled={!ok}
                        aria-pressed={on}
                        aria-label={"Level " + l.n + ", " + l.name + (ok ? "" : ", not allowed")}
                        onClick={() => setWager(l.n)}
                      >
                        <span className="ry-d ry-lv-n">{l.n}</span>
                        <span className="ry-bars" aria-hidden="true">
                          {[0, 1, 2, 3, 4].map((k) => (
                            <i key={k} className={k < l.n ? "on" : ""} style={{ height: 3 + 2 * k }} />
                          ))}
                        </span>
                      </button>
                    );
                  })}
                </div>
                <div className="ry-info" aria-live="polite">
                  {wager ? (
                    <>
                      <div>
                        <p className="ry-d ry-info-title">Level {wager} · {LEVELS[wager - 1].name}</p>
                        <p className="ry-info-sub">
                          Right answer: tile {destPos}, {dest.title.toLowerCase() === "the reckoning" ? "the Reckoning" : dest.title}
                        </p>
                      </div>
                      <span className="ry-gain">+{wager}</span>
                    </>
                  ) : (
                    <p className="ry-info-sub">Pick a level to see where a right answer takes you.</p>
                  )}
                </div>
              </section>

              <div>
                <p className="ry-hint">
                  {me.fx.backslide > 0
                    ? "Backslide: a wrong answer sends you back " + (wager || "the number you chose")
                    : "Wrong answer: you stay where you are"}
                </p>
                <button className="ry-btn ry-primary" disabled={!wager} onClick={() => setPhase("question")}>
                  Show the question <Icon name="arrow" />
                </button>
              </div>
            </>
          )}

          {/* ---- question: the answer stays hidden ---- */}
          {phase === "question" && q && (
            <>
              <section className="ry-card ry-q">
                <div className="ry-row">
                  <span className="ry-pill">Level {wager} · {LEVELS[wager - 1].name}</span>
                  <span className="ry-meta">{titleCase(topic.cat)}</span>
                </div>
                <p className="ry-meta2">{topic.sub}</p>
                <p className="ry-question">{q.q}</p>
                <div className="ry-covered">
                  <Icon name="eyeOff" size={18} />
                  Answer hidden
                </div>
              </section>
              <div>
                <p className="ry-hint">Say your answer out loud first.</p>
                <button className="ry-btn ry-primary" onClick={() => setPhase("judge")}>
                  <Icon name="eye" /> Show the answer
                </button>
              </div>
            </>
          )}

          {/* ---- judge ---- */}
          {phase === "judge" && q && (
            <>
              <section className="ry-card ry-q">
                <div className="ry-row">
                  <span className="ry-pill">Level {wager} · {LEVELS[wager - 1].name}</span>
                  <span className="ry-meta">{titleCase(topic.cat)}</span>
                </div>
                <p className="ry-question ry-dim">{q.q}</p>
                <div className="ry-answer">
                  <p className="ry-label ry-success-t">Answer</p>
                  <p className="ry-d ry-answer-text">{q.a[0]}</p>
                  {q.a.length > 1 && <p className="ry-alts">Also accept: {q.a.slice(1).join(" · ")}</p>}
                </div>
              </section>
              <div>
                <p className="ry-hint">The other teams decide.</p>
                <div className="ry-judge">
                  <button className="ry-btn ry-danger" onClick={() => judge(false)}>
                    <Icon name="x" /> Missed it
                  </button>
                  <button className="ry-btn ry-success" onClick={() => judge(true)}>
                    <Icon name="check" /> Got it · +{wager}
                  </button>
                </div>
              </div>
            </>
          )}

          {/* ---- fortune: the list stays hidden ---- */}
          {phase === "fortune" && fortuneQ && (
            <>
              <section className="ry-card ry-q ry-k-f">
                <div className="ry-row">
                  <span className="ry-pill ry-pill-f"><Icon name="star" size={14} fill /> Fortune</span>
                  <span className="ry-meta">{titleCase(fortuneQ.cat)}</span>
                </div>
                <p className="ry-question">{fortuneQ.ask}</p>
                <p className="ry-sub">
                  There are <b>{fortuneQ.list.length}</b>. You move one space for each one you name.
                </p>
                <div className="ry-covered">
                  <Icon name="eyeOff" size={18} />
                  List hidden
                </div>
              </section>
              <button className="ry-btn ry-primary" onClick={() => setPhase("fortuneScore")}>
                <Icon name="eye" /> Reveal the list and score it
              </button>
            </>
          )}

          {phase === "fortuneScore" && fortuneQ && (
            <>
              <section className="ry-card ry-q ry-k-f">
                <p className="ry-label">Tap each one they named</p>
                <p className="ry-question ry-dim">{fortuneQ.ask}</p>
                <div className="ry-chips">
                  {fortuneQ.list.map((item, i) => {
                    const on = ticks.has(i);
                    return (
                      <button
                        key={i}
                        data-tick
                        className={"ry-chip-btn" + (on ? " is-on" : "")}
                        aria-pressed={on}
                        onClick={() => {
                          const s = new Set(ticks);
                          s.has(i) ? s.delete(i) : s.add(i);
                          setTicks(s);
                        }}
                      >
                        {on && <Icon name="check" size={16} />}
                        {item}
                      </button>
                    );
                  })}
                </div>
              </section>
              <button className="ry-btn ry-primary" onClick={scoreFortune}>
                Move {ticks.size} space{ticks.size === 1 ? "" : "s"}
              </button>
            </>
          )}

          {/* ---- the Reckoning ---- */}
          {phase === "final" && orderQ && (
            <>
              <section className="ry-card ry-q ry-k-x">
                <div className="ry-row">
                  <span className="ry-pill ry-pill-x"><Icon name="crown" size={14} /> The Reckoning</span>
                  <span className="ry-meta">All or nothing</span>
                </div>
                <p className="ry-question">{orderQ.ask}</p>
                <ol className="ry-slots">
                  {orderQ.list.map((_, i) => (
                    <li key={i} className={"ry-slot" + (pick[i] ? " is-full" : "")}>
                      <span className="ry-slot-n">{i + 1}</span>
                      <span className="ry-slot-v">{pick[i] || (i === pick.length ? "Tap an item below" : "Empty")}</span>
                      {pick[i] && (
                        <button
                          className="ry-slot-x"
                          aria-label={"Remove " + pick[i]}
                          onClick={() => setPick(pick.filter((_, j) => j !== i))}
                        >
                          <Icon name="x" size={16} />
                        </button>
                      )}
                    </li>
                  ))}
                </ol>
                {pick.length < orderQ.list.length && (
                  <div className="ry-chips">
                    {orderQ.shuffled
                      .filter((v) => !pick.includes(v))
                      .map((v) => (
                        <button key={v} data-item className="ry-chip-btn" onClick={() => setPick([...pick, v])}>
                          {v}
                        </button>
                      ))}
                  </div>
                )}
              </section>
              <button
                className="ry-btn ry-primary ry-reckon-btn"
                disabled={pick.length !== orderQ.list.length}
                onClick={lockOrder}
              >
                Lock in the order
              </button>
            </>
          )}

          {phase === "finalResult" && orderQ && (
            <>
              <section className="ry-card ry-q ry-k-x">
                <p className="ry-d ry-result ry-bad"><Icon name="x" size={26} /> Not the right order</p>
                <ol className="ry-proof">
                  {orderQ.list.map((v, i) => (
                    <li key={i} className="ry-proof-row">
                      <span className={"ry-slot-n" + (pick[i] === v ? " is-good" : " is-bad")}>{i + 1}</span>
                      <span className="ry-proof-v">
                        {v}
                        {pick[i] !== v && <small>You said: {pick[i]}</small>}
                      </span>
                      <span className={pick[i] === v ? "ry-good" : "ry-bad"}>
                        <Icon name={pick[i] === v ? "check" : "x"} size={18} />
                      </span>
                    </li>
                  ))}
                </ol>
                <p className="ry-sub">You stay on tile 60. Try again next turn.</p>
              </section>
              <button className="ry-btn ry-primary" onClick={nextTurn}>Pass to {nextName}</button>
            </>
          )}

          {/* ---- moving ---- */}
          {phase === "move" && (
            <section className="ry-card ry-moving" aria-live="polite">
              <span className="ry-hop" style={{ background: me.color }} aria-hidden="true" />
              <p className="ry-d">Moving…</p>
              <span className="ry-moving-tile">Tile {me.pos}</span>
            </section>
          )}

          {/* ---- misfortune ---- */}
          {phase === "misfortune" && misf && (
            <>
              <section className="ry-card ry-q ry-k-m">
                <div className="ry-turn-row">
                  <span className="ry-turn-ic"><Icon name="alert" size={26} /></span>
                  <div>
                    <p className="ry-label ry-bad-t">Misfortune</p>
                    <h2 className="ry-d ry-turn-title">{misf.title}</h2>
                  </div>
                </div>
                <p className="ry-sub ry-strong">{misf.text}</p>
              </section>
              <button className="ry-btn ry-primary" onClick={nextTurn}>Pass to {nextName}</button>
            </>
          )}

          {/* ---- result ---- */}
          {phase === "result" && outcome && (
            <>
              <section className="ry-card ry-q" aria-live="polite">
                {outcome.kind === "skipped" && (
                  <p className="ry-d ry-result ry-bad"><Icon name="x" size={26} /> {me.name} loses this turn</p>
                )}
                {outcome.kind === "right" && (
                  <p className="ry-d ry-result ry-good"><Icon name="check" size={26} /> {me.name} moves {outcome.wager} to tile {me.pos}</p>
                )}
                {outcome.kind === "wrong" && (
                  <>
                    <p className="ry-d ry-result ry-bad">
                      <Icon name="x" size={26} />
                      {me.fx.backslide > 0 ? " Back " + outcome.wager + " to tile " + me.pos : " No move"}
                    </p>
                    {topic && (
                      <p className="ry-sub">
                        The answer was <b>{topic.q[outcome.wager - 1].a[0]}</b>.
                      </p>
                    )}
                  </>
                )}
                {outcome.kind === "fortune" && (
                  <p className={"ry-d ry-result " + (outcome.n ? "ry-good" : "ry-bad")}>
                    <Icon name={outcome.n ? "check" : "x"} size={26} />
                    {outcome.n === 0 ? " Nothing named. No move" : " " + me.name + " moves " + outcome.n + " to tile " + me.pos}
                  </p>
                )}
              </section>
              <button className="ry-btn ry-primary" onClick={nextTurn}>Pass to {nextName}</button>
            </>
          )}
        </div>
      </div>
    </Shell>
  );
}

/* ---------------- the strip: nine tiles around you ---------------- */
function Strip({ teams, activeIdx }) {
  const me = teams[activeIdx];
  const from = Math.max(1, Math.min(me.pos - 4, LAST - 8));
  const tiles = [];
  for (let k = 0; k < 9; k++) tiles.push(from + k);
  const atStart = teams.filter((t) => t.pos === 0).length;
  return (
    <section className="ry-card" aria-label="The board around you">
      <div className="ry-row">
        <p className="ry-label">The board</p>
        <p className="ry-label ry-plain">{atStart > 0 ? atStart + " at the start" : teams.length + " teams"}</p>
      </div>
      <div className="ry-strip">
        {tiles.map((n) => {
          const info = tileInfo(n);
          const here = teams.map((t, i) => ({ ...t, i })).filter((t) => t.pos === n);
          return (
            <div
              key={n}
              className={"ry-tile ry-tile-" + info.kind + (n === me.pos ? " is-cur" : "")}
              title={n + " · " + info.title}
            >
              {info.kind === "c" ? <span>{info.code}</span> : <Icon name={info.icon} size={16} fill={info.kind === "f"} stroke={2.6} />}
              {here.length > 0 && (
                <span className="ry-pawns">
                  {here.map((t) => (
                    <span key={t.i} className="ry-pawn" style={{ background: t.color }} />
                  ))}
                </span>
              )}
            </div>
          );
        })}
      </div>
      <div className="ry-strip ry-nums" aria-hidden="true">
        {tiles.map((n) => (
          <span key={n} className={n === me.pos ? "is-cur" : ""}>{n}</span>
        ))}
      </div>
      <div className="ry-standings">
        {teams.map((t, i) => (
          <span key={i} className={"ry-stand" + (i === activeIdx ? " is-me" : "")}>
            <span className="ry-dot" style={{ background: t.color }} aria-hidden="true" />
            {t.name}
            <b>{t.pos}</b>
          </span>
        ))}
      </div>
    </section>
  );
}

/* ---------------- the full board: 60 tiles, snaking ---------------- */
function Board({ teams, activeIdx }) {
  const rows = [];
  for (let r = 0; r < 10; r++) {
    const row = [];
    for (let c = 0; c < 6; c++) row.push(r * 6 + c + 1);
    if (r % 2 === 1) row.reverse();
    rows.push(row);
  }
  const atStart = teams.map((t, i) => ({ ...t, i })).filter((t) => t.pos === 0);

  return (
    <section className="ry-card ry-board" aria-label="The full board">
      <div className="ry-board-start">
        <span className="ry-label">Start</span>
        <span className="ry-pawns-inline">
          {atStart.map((t) => (
            <span key={t.i} className={"ry-pawn" + (t.i === activeIdx ? " is-me" : "")} style={{ background: t.color }} />
          ))}
        </span>
      </div>
      {rows.map((row, ri) => (
        <div key={ri} className="ry-board-row">
          {row.map((n) => {
            const info = tileInfo(n);
            const here = teams.map((x, i) => ({ ...x, i })).filter((x) => x.pos === n);
            return (
              <div key={n} className={"ry-btile ry-tile-" + info.kind + (teams[activeIdx] && teams[activeIdx].pos === n ? " is-cur" : "")} title={n + " · " + info.title}>
                <span className="ry-btile-n">{n}</span>
                {info.kind === "c" ? <span className="ry-btile-c">{info.code}</span> : <Icon name={info.icon} size={15} fill={info.kind === "f"} stroke={2.6} />}
                {here.length > 0 && (
                  <span className="ry-pawns ry-pawns-in">
                    {here.map((x) => (
                      <span key={x.i} className={"ry-pawn" + (x.i === activeIdx ? " is-me" : "")} style={{ background: x.color }} />
                    ))}
                  </span>
                )}
              </div>
            );
          })}
        </div>
      ))}
      <div className="ry-legend" aria-hidden="true">
        <span><Icon name="star" size={13} fill /> Fortune</span>
        <span><Icon name="alert" size={13} /> Misfortune</span>
        <span><Icon name="crown" size={13} /> The Reckoning</span>
        <span>Other tiles: the category's first three letters</span>
      </div>
    </section>
  );
}

/* ---------------- icons: stroke SVG, no emoji ---------------- */
const ICONS = {
  globe: [{ c: [12, 12, 10] }, "M2 12h20", "M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"],
  flask: ["M9 3h6", "M10 3v6.5L4.6 18.4A1.8 1.8 0 0 0 6.1 21h11.8a1.8 1.8 0 0 0 1.5-2.6L14 9.5V3", "M7.5 15h9"],
  leaf: ["M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.5 19 2c1 2 2 4.2 2 8 0 5.5-4.8 10-10 10z", "M2 21c0-3 1.9-5.4 5.1-6 2.4-.5 4.9-2 5.9-3"],
  landmark: ["M3 22h18", "M6 18v-7", "M10 18v-7", "M14 18v-7", "M18 18v-7", "M12 2l9 6H3z"],
  book: ["M2 4h6a4 4 0 0 1 4 4v13a3 3 0 0 0-3-3H2z", "M22 4h-6a4 4 0 0 0-4 4v13a3 3 0 0 1 3-3h7z"],
  music: ["M9 18V5l12-2v13", { c: [6, 18, 3] }, { c: [18, 16, 3] }],
  trophy: ["M6 9H4.5a2.5 2.5 0 0 1 0-5H6", "M18 9h1.5a2.5 2.5 0 0 0 0-5H18", "M4 22h16", "M10 14.7V17c0 .6-.5 1-1 1.2C7.9 18.8 7 20.2 7 22", "M14 14.7V17c0 .6.5 1 1 1.2 1.1.6 2 2 2 3.8", "M18 2H6v7a6 6 0 0 0 12 0z"],
  film: [{ r: [2, 2, 20, 20, 2.5] }, "M7 2v20", "M17 2v20", "M2 12h20", "M2 7h5", "M2 17h5", "M17 17h5", "M17 7h5"],
  utensils: ["M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2", "M7 2v20", "M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3zm0 0v7"],
  flag: ["M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z", "M4 22v-7"],
  star: ["M12 2.5l2.9 6 6.6.8-4.9 4.5 1.3 6.5L12 17l-5.9 3.3 1.3-6.5L2.5 9.3l6.6-.8z"],
  alert: ["M10.3 3.9L1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z", "M12 9v4", "M12 17h.01"],
  crown: ["M2 6l4 12h12l4-12-6 5-4-7-4 7z", "M5 21h14"],
  play: ["M6 3l14 9-14 9z"],
  swap: ["M17 3l4 4-4 4", "M3 11V9a2 2 0 0 1 2-2h16", "M7 21l-4-4 4-4", "M21 13v2a2 2 0 0 1-2 2H3"],
  arrow: ["M5 12h14", "M13 6l6 6-6 6"],
  check: ["M20 6L9 17l-5-5"],
  download: ["M12 3v12", "M7 10l5 5 5-5", "M5 21h14"],
  x: ["M18 6L6 18", "M6 6l12 12"],
  eye: ["M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z", { c: [12, 12, 3] }],
  eyeOff: ["M9.9 4.2A10.4 10.4 0 0 1 12 4c6.5 0 10 8 10 8a17.6 17.6 0 0 1-2.2 3.2", "M6.6 6.6A17.4 17.4 0 0 0 2 12s3.5 8 10 8a9.7 9.7 0 0 0 5.4-1.6", "M14.1 14.1a3 3 0 1 1-4.2-4.2", "M2 2l20 20"],
  grid: [{ r: [3, 3, 7, 7, 1.5] }, { r: [14, 3, 7, 7, 1.5] }, { r: [3, 14, 7, 7, 1.5] }, { r: [14, 14, 7, 7, 1.5] }],
};

function Icon({ name, size = 20, stroke = 2.2, fill = false }) {
  const parts = ICONS[name] || [];
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill={fill ? "currentColor" : "none"}
      stroke="currentColor"
      strokeWidth={stroke}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      style={{ flex: "0 0 auto" }}
    >
      {parts.map((p, i) =>
        typeof p === "string" ? (
          <path key={i} d={p} />
        ) : p.c ? (
          <circle key={i} cx={p.c[0]} cy={p.c[1]} r={p.c[2]} />
        ) : (
          <rect key={i} x={p.r[0]} y={p.r[1]} width={p.r[2]} height={p.r[3]} rx={p.r[4] || 0} />
        )
      )}
    </svg>
  );
}

/* ---------------- shell + design tokens ---------------- */
function Shell({ children }) {
  return (
    <div className="ry">
      <style>{CSS}</style>
      {children}
    </div>
  );
}

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Nunito:wght@400;600;700;800&display=swap');
.ry{
  --bg:#12101F; --surface:#1E1A33; --surface-2:#2A2547; --edge:#0B0918; --line:rgba(255,255,255,.08);
  --text:#F5F3FF; --muted:#B8B2D9;
  --primary:#FFD23F; --on-primary:#1A1400; --primary-edge:#B8901A;
  --accent:#6D4AFF; --accent-edge:#3E26B8;
  --fortune:#FFB547; --fortune-bg:rgba(255,181,71,.15);
  --danger:#FF6B81; --danger-bg:rgba(255,92,122,.15);
  --success:#2BD9A4; --on-success:#04261C; --success-edge:#149872; --success-bg:rgba(43,217,164,.14);
  --r-lg:22px; --r-md:16px; --r-sm:10px;
  min-height:100vh; background:var(--bg); color:var(--text);
  font:400 16px/1.5 'Nunito',system-ui,sans-serif; -webkit-font-smoothing:antialiased;
  padding:16px 16px 40px;
}
.ry *{box-sizing:border-box}
.ry p,.ry h1,.ry h2,.ry h3{margin:0}
.ry-d{font-family:'Fredoka','Nunito',system-ui,sans-serif}
.ry-wrap{max-width:480px;margin:0 auto;display:flex;flex-direction:column;gap:16px}
.ry-stack{display:flex;flex-direction:column;gap:16px}
.ry button{font:inherit;color:inherit;border:0;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent}
.ry button:disabled{cursor:not-allowed}
.ry button:focus-visible,.ry input:focus-visible{outline:3px solid var(--primary);outline-offset:3px}
.ry-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

.ry-card{background:var(--surface);border-radius:var(--r-lg);padding:16px;display:flex;flex-direction:column;gap:10px}
.ry-row{display:flex;justify-content:space-between;align-items:center;gap:10px}
.ry-label{font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.ry-plain{letter-spacing:.02em;text-transform:none}
.ry-sub{font-size:15px;line-height:1.5;color:var(--muted)}
.ry-sub b{color:var(--text)}
.ry-strong{color:var(--text);font-weight:700;font-size:16px}
.ry .ry-hint{text-align:center;font-size:14px;font-weight:700;color:var(--muted);margin:0 0 10px}
.ry-h{font-size:23px;font-weight:600;line-height:1.2}

/* buttons */
.ry .ry-btn{width:100%;min-height:56px;border-radius:18px;display:flex;align-items:center;justify-content:center;gap:10px;padding:12px 18px;
  font:700 19px/1.2 'Fredoka','Nunito',sans-serif;transition:transform 110ms ease-out,box-shadow 110ms ease-out,opacity 150ms}
.ry .ry-primary{background:var(--primary);color:var(--on-primary);box-shadow:0 6px 0 var(--primary-edge)}
.ry .ry-success{background:var(--success);color:var(--on-success);box-shadow:0 6px 0 var(--success-edge)}
.ry .ry-danger{background:var(--danger-bg);color:var(--danger);box-shadow:0 6px 0 var(--edge)}
.ry .ry-btn:active:not(:disabled){transform:translateY(4px);box-shadow:0 2px 0 var(--edge)}
.ry .ry-primary:active:not(:disabled){box-shadow:0 2px 0 var(--primary-edge)}
.ry .ry-success:active:not(:disabled){box-shadow:0 2px 0 var(--success-edge)}
.ry .ry-btn:disabled{background:var(--surface-2);color:var(--muted);box-shadow:none}
.ry-judge{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.ry-icon-btn{width:44px;height:44px;border-radius:14px;background:var(--surface-2) !important;display:grid;place-items:center}

/* setup */
.ry-hero{display:flex;flex-direction:column;gap:8px;padding:12px 4px 4px}
.ry-title{font-size:44px;line-height:1;font-weight:700;letter-spacing:-.01em}
.ry-lede{font-size:16px;line-height:1.55;color:var(--muted)}
.ry-lede b{color:var(--text)}
.ry-rules{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.ry-rules li{display:flex;gap:14px;align-items:center;background:var(--surface);border-radius:var(--r-md);padding:12px 14px}
.ry-rules li > span:last-child{display:flex;flex-direction:column;font-size:14px;line-height:1.4;color:var(--muted)}
.ry-rules b{font:600 17px/1.3 'Fredoka','Nunito',sans-serif;color:var(--text)}
.ry-rule-ic{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;flex:0 0 auto}
.ry-ic-accent{background:rgba(109,74,255,.22);color:#B9A6FF}
.ry-ic-fortune{background:var(--fortune-bg);color:var(--fortune)}
.ry-ic-reckon{background:var(--danger-bg);color:var(--danger)}
.ry-count{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:4px}
.ry-names{display:flex;flex-direction:column;gap:10px;margin-top:8px}
.ry-name-row{display:flex;align-items:center;gap:12px}
.ry-input{flex:1;min-height:48px;border-radius:14px;border:2px solid transparent;background:var(--surface-2);color:var(--text);
  padding:10px 14px;font:700 16px 'Nunito',sans-serif}
.ry-dot{width:12px;height:12px;border-radius:50%;flex:0 0 auto;display:inline-block}
.ry-dot-lg{width:18px;height:18px}

/* header */
.ry-head{display:flex;align-items:center;justify-content:space-between;gap:12px}
.ry-who{display:flex;align-items:center;gap:14px;min-width:0}
.ry-avatar{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:20px;color:#12101F;flex:0 0 auto}
.ry-who-kick{font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--primary)}
.ry-who-name{font:600 21px/1.15 'Fredoka','Nunito',sans-serif;overflow-wrap:anywhere}
.ry-who-sub{font-size:13px;font-weight:700;color:var(--muted)}
.ry-fx{display:flex;flex-wrap:wrap;gap:8px}
.ry-fx-chip{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;background:var(--danger-bg);color:var(--danger);font-size:13px;font-weight:800}

/* strip */
.ry-strip{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));gap:5px;margin-top:6px}
.ry-tile{position:relative;height:48px;border-radius:var(--r-sm);background:var(--surface-2);display:grid;place-items:center;
  font-size:12px;font-weight:800;color:var(--muted)}
.ry-tile-f{background:var(--fortune-bg);color:var(--fortune)}
.ry-tile-m,.ry-tile-x{background:var(--danger-bg);color:var(--danger)}
.ry-tile.is-cur{background:var(--accent);color:#fff;box-shadow:0 4px 0 var(--accent-edge);transform:translateY(-3px)}
.ry-nums{margin-top:0}
.ry-nums span{text-align:center;font-size:12px;font-weight:700;color:var(--muted)}
.ry-nums span.is-cur{color:var(--text)}
.ry-pawns{position:absolute;top:-7px;left:0;right:0;display:flex;justify-content:center;gap:2px}
.ry-pawn{width:13px;height:13px;border-radius:50%;border:2px solid var(--surface);display:inline-block;flex:0 0 auto}
.ry-pawn.is-me{border-color:#fff}
.ry-standings{display:flex;flex-wrap:wrap;gap:6px;margin-top:4px}
.ry-stand{display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:999px;background:var(--surface-2);font-size:13px;font-weight:700;color:var(--muted)}
.ry-stand b{color:var(--text);font-weight:800}
.ry-stand.is-me{color:var(--text);box-shadow:inset 0 0 0 2px rgba(255,255,255,.22)}

/* full board */
.ry-board{gap:5px}
.ry-board-start{display:flex;align-items:center;gap:10px;padding:6px 10px;border-radius:var(--r-sm);border:2px dashed var(--line);min-height:36px}
.ry-pawns-inline{display:flex;gap:4px}
.ry-board-row{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:5px}
.ry-btile{position:relative;aspect-ratio:1/1;border-radius:var(--r-sm);background:var(--surface-2);display:grid;place-items:center;color:var(--muted)}
.ry-btile-n{position:absolute;top:3px;left:6px;font-size:10px;font-weight:700;opacity:.7}
.ry-btile-c{font-size:12px;font-weight:800}
.ry-pawns-in{top:auto;bottom:4px}
.ry-btile.ry-tile-f{background:var(--fortune-bg);color:var(--fortune)}
.ry-btile.ry-tile-m,.ry-btile.ry-tile-x{background:var(--danger-bg);color:var(--danger)}
.ry-btile.is-cur{box-shadow:inset 0 0 0 2px var(--accent)}
.ry-legend{display:flex;flex-wrap:wrap;gap:6px 14px;padding-top:6px;font-size:12px;font-weight:700;color:var(--muted)}
.ry-legend span{display:inline-flex;align-items:center;gap:5px}

/* turn card */
.ry-turn-row{display:flex;align-items:center;gap:12px}
.ry-turn-ic{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:var(--surface-2);color:var(--text);flex:0 0 auto}
.ry-turn-title{font-size:30px;line-height:1.1;font-weight:700}
.ry-k-c .ry-turn-ic{background:rgba(109,74,255,.25);color:#C8BAFF}
.ry-k-f .ry-turn-ic{background:var(--fortune-bg);color:var(--fortune)}
.ry-k-m .ry-turn-ic,.ry-k-x .ry-turn-ic{background:var(--danger-bg);color:var(--danger)}
.ry-k-f{box-shadow:inset 0 0 0 2px rgba(255,181,71,.35)}
.ry-k-m,.ry-k-x{box-shadow:inset 0 0 0 2px rgba(255,107,129,.35)}

/* category card */
.ry-cat{position:relative;overflow:hidden;background:var(--accent);border-radius:var(--r-lg);padding:20px;box-shadow:0 6px 0 var(--accent-edge);
  display:flex;flex-direction:column;gap:6px}
.ry-cat-deco{position:absolute;right:-26px;top:-30px;color:rgba(255,255,255,.14)}
.ry-on-accent{color:rgba(255,255,255,.88)}
.ry .ry-cat-title{font-size:36px;line-height:1.05;font-weight:700;margin-bottom:6px}
.ry-topic-row{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;position:relative}
.ry-chip{background:rgba(255,255,255,.18);border-radius:999px;padding:8px 14px;font-weight:800;font-size:15px}
.ry .ry-swap{min-height:44px;padding:0 14px;border-radius:999px;background:rgba(11,9,24,.32);display:inline-flex;align-items:center;gap:6px;font-weight:800;font-size:14px;color:#fff}

/* level picker */
.ry-levels{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:12px}
.ry .ry-lv{height:72px;border-radius:var(--r-md);background:var(--surface-2);box-shadow:0 5px 0 var(--edge);color:var(--text);
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;transition:transform 140ms ease-out,box-shadow 140ms ease-out}
.ry-lv-n{font-size:28px;font-weight:700;line-height:1}
.ry .ry-lv.is-on{background:var(--primary);color:var(--on-primary);box-shadow:0 5px 0 var(--primary-edge);transform:translateY(-4px)}
.ry .ry-lv:disabled{opacity:.3;box-shadow:none}
.ry .ry-count .ry-lv{height:60px}
.ry-bars{display:flex;gap:3px;align-items:flex-end;height:11px}
.ry-bars i{width:4px;border-radius:2px;background:currentColor;opacity:.28;display:block}
.ry-bars i.on{opacity:1}
.ry-info{margin-top:14px;display:flex;align-items:center;justify-content:space-between;gap:12px;background:var(--surface);border-radius:var(--r-md);padding:12px 16px;min-height:68px}
.ry-info-title{font-size:18px;font-weight:600;line-height:1.25}
.ry-info-sub{font-size:14px;font-weight:700;color:var(--muted)}
.ry-gain{background:var(--success-bg);color:var(--success);border-radius:999px;padding:6px 12px;font-weight:800;font-size:15px;white-space:nowrap}

/* question + answer */
.ry-pill{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;background:rgba(255,210,63,.14);color:var(--primary);font-size:13px;font-weight:800}
.ry-pill-f{background:var(--fortune-bg);color:var(--fortune)}
.ry-pill-x{background:var(--danger-bg);color:var(--danger)}
.ry-meta{font-size:13px;font-weight:800;color:var(--muted);text-align:right}
.ry .ry-meta2{font-size:14px;font-weight:700;color:var(--muted);margin-top:-2px}
.ry-question{font-size:22px;line-height:1.35;font-weight:800;color:var(--text)}
.ry-dim{font-size:17px;font-weight:700;color:var(--muted)}
.ry-covered{display:flex;align-items:center;justify-content:center;gap:8px;min-height:72px;border-radius:var(--r-md);
  border:2px dashed rgba(255,255,255,.14);color:var(--muted);font-weight:800;font-size:14px;margin-top:4px}
.ry-answer{border-radius:var(--r-md);background:var(--success-bg);padding:14px 16px;display:flex;flex-direction:column;gap:4px;margin-top:4px}
.ry-success-t{color:var(--success)}
.ry-answer-text{font-size:26px;line-height:1.15;font-weight:700}
.ry-alts{font-size:14px;color:var(--muted);font-weight:700}

/* chips: fortune list, reckoning items */
.ry-chips{display:flex;flex-wrap:wrap;gap:8px}
.ry .ry-chip-btn{min-height:44px;padding:8px 14px;border-radius:14px;background:var(--surface-2);box-shadow:0 4px 0 var(--edge);
  font-weight:800;font-size:15px;color:var(--text);display:inline-flex;align-items:center;gap:6px;text-align:left;transition:transform 110ms ease-out}
.ry .ry-chip-btn:active{transform:translateY(3px);box-shadow:0 1px 0 var(--edge)}
.ry .ry-chip-btn.is-on{background:var(--success);color:var(--on-success);box-shadow:0 4px 0 var(--success-edge)}

/* reckoning slots */
.ry-slots{list-style:none;margin:2px 0 0;padding:0;display:flex;flex-direction:column;gap:8px}
.ry-slot{display:flex;align-items:center;gap:12px;min-height:52px;padding:4px 6px 4px 12px;border-radius:14px;border:2px dashed rgba(255,255,255,.14);color:var(--muted);font-weight:700}
.ry-slot.is-full{border:2px solid transparent;background:var(--surface-2);color:var(--text)}
.ry-slot-n{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--danger-bg);color:var(--danger);font:700 14px 'Fredoka',sans-serif;flex:0 0 auto}
.ry-slot-n.is-good{background:var(--success-bg);color:var(--success)}
.ry-slot-n.is-bad{background:var(--danger-bg);color:var(--danger)}
.ry-slot-v{flex:1;font-size:15px}
.ry .ry-slot-x{width:44px;height:44px;border-radius:12px;display:grid;place-items:center;color:var(--muted)}
.ry .ry-reckon-btn{background:#FF6B81;color:#2A0710;box-shadow:0 6px 0 #B23A50}
.ry .ry-reckon-btn:active:not(:disabled){box-shadow:0 2px 0 #B23A50}

/* proof list */
.ry-proof{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px;width:100%}
.ry-proof-row{display:flex;align-items:center;gap:12px;padding:8px 12px;border-radius:14px;background:var(--surface-2);text-align:left}
.ry-proof-v{flex:1;font-weight:800;font-size:15px;display:flex;flex-direction:column}
.ry-proof-v small{font-size:13px;font-weight:700;color:var(--muted)}

/* results */
.ry-result{display:flex;align-items:center;gap:10px;font-size:22px;font-weight:600;line-height:1.25}
.ry-good{color:var(--success);display:inline-flex}
.ry-bad{color:var(--danger);display:inline-flex}
.ry-bad-t{color:var(--danger)}
.ry-moving{align-items:center;text-align:center;padding:22px 16px;gap:8px}
.ry-moving p{font-size:22px;font-weight:600}
.ry-moving-tile{font-size:14px;font-weight:800;color:var(--muted)}
.ry-hop{width:22px;height:22px;border-radius:50%;box-shadow:0 0 0 3px var(--surface),0 0 0 5px rgba(255,255,255,.25);animation:ry-hop .32s ease-in-out infinite alternate}
@keyframes ry-hop{from{transform:translateY(0)}to{transform:translateY(-10px)}}
.ry-win{align-items:center;text-align:center;padding:24px 16px}
.ry-win-ic{width:88px;height:88px;border-radius:28px;background:var(--surface-2);display:grid;place-items:center}

.ry .ry-ghost{background:var(--surface-2);color:var(--text);box-shadow:0 5px 0 var(--edge)}
.ry-resume{box-shadow:inset 0 0 0 2px rgba(255,210,63,.35)}
.ry .ry-ios{margin:4px 0 0}
.ry-ios b{color:var(--text)}

@media (prefers-reduced-motion: reduce){.ry *{transition:none!important;animation:none!important}}
`;
